"use client";

import { useEffect } from "react";

/**
 * Short confetti burst falling from the top of the screen (~3.5 s).
 * Pieces are generated by the caller (in an event handler) via makeConfettiPieces().
 *
 * @param {{ pieces: ReturnType<typeof makeConfettiPieces>; onDone: () => void }} props
 */
export function Confetti({ pieces, onDone }) {
  useEffect(() => {
    const t = setTimeout(onDone, 3600);
    return () => clearTimeout(t);
  }, [onDone]);

  return (
    <div className="pointer-events-none fixed inset-0 z-[100] overflow-hidden" aria-hidden>
      {pieces.map((p) => (
        <span
          key={p.id}
          className="confetti-piece"
          style={{
            left: `${p.left}%`,
            width: p.w,
            height: p.h,
            background: p.color,
            "--confetti-drift": `${p.drift}px`,
            "--confetti-spin": `${p.spin}deg`,
            "--confetti-dur": `${p.dur}s`,
            "--confetti-delay": `${p.delay}s`,
          }}
        />
      ))}
    </div>
  );
}

const HUES = [25, 70, 145, 200, 260, 330];

/** @param {number} [count] */
export function makeConfettiPieces(count = 70) {
  return Array.from({ length: count }, (_, id) => {
    const w = 6 + Math.random() * 6;
    return {
      id,
      left: Math.random() * 100,
      w,
      h: w * (0.5 + Math.random() * 0.9),
      color: `oklch(72% 0.17 ${HUES[Math.floor(Math.random() * HUES.length)]})`,
      drift: (Math.random() - 0.5) * 160,
      spin: (Math.random() - 0.5) * 1080,
      dur: 2 + Math.random() * 0.9,
      delay: Math.random() * 0.4,
    };
  });
}
